    name: "Alex",
    age: 25
};

const name = user.name;
const age = user.age;

const user = {
    name: "Alex",
    age: 25
};

const { name, age } = user;

const user = {
    name: "Alex",
    age: 25
};

const { name, age } = user;

const user = {
    name: "Alex",
    age: 25,
    city: "Almaty"
};

const { name } = user;

console.log(name);

const user = {
    name: "Alex",
    age: 25
};

const { name: userName, age: userAge } = user;

console.log(userName);
console.log(userAge);

const user = {
    name: "Alex"
};

const { name, age = 18 } = user;

console.log(name);
console.log(age);

const user = {
    name: "Alex",
    age: 25
};

const { age = 18 } = user;

console.log(age);

const user = {
    name: "Alex",
    address: {
        city: "Almaty",
        country: "Kazakhstan"
    }
};

const {
    address: { city, country }
} = user;

console.log(city);
console.log(country);

const user = {
    name: "Alex",
    age: 25
};

let name;
let age;

({ name, age } = user);

function showUser({ name, age }) {
    console.log(name);
    console.log(age);
}

const user = {
    name: "Alex",
    age: 25
};

showUser(user);
